CREATE VIEW V1 AS
  SELECT 부서, SUM(급여) AS 합
  FROM   사원
  GROUP  BY 부서;
CREATE VIEW V2 AS
  SELECT 이름, 급여
  FROM   사원
  WHERE  부서 = 10;

-- ㉠
UPDATE V1 SET 합 = 0;
-- ㉡
